import copy
def repair_quota(config,before,after,approval):
    old=config['limits']['cpu_nanos']
    expected=approval.get('expected_cpu_nanos');target=approval.get('target_cpu_nanos');budget=approval.get('budget_cpu_nanos')
    if any(type(value) is not int for value in (old,expected,target,budget)) or old!=expected or not 0<old<target<=budget<=2000000000:
        raise ValueError('explicit approved increase and matching baseline required')
    for key in ('usage_usec','nr_periods','nr_throttled','throttled_usec'):
        if any(type(sample.get(key)) is not int or sample[key]<0 for sample in (before,after)) or after[key]<before[key]:
            raise ValueError('invalid/reset cgroup counter')
    if any(after[key]<=before[key] for key in ('usage_usec','nr_periods','nr_throttled','throttled_usec')):
        raise ValueError('no observed active throttling interval')
    if config.get('user')!='1000:1000' or config.get('privileged') is not False or config.get('cap_add')!=[]:
        raise ValueError('preserve declared ordinary execution')
    result=copy.deepcopy(config);result['limits']['cpu_nanos']=target
    return result
